-- Migration 0014: the official company name is "Kuzikode Intelligent Technologies" (R9, docs/redesign/REFINEMENTS.md §9).
-- Only rows whose text still contains the old seeded name are touched (REPLACE is a no-op elsewhere). Issued documents keep
-- their immutable business snapshots. content_version is bumped so every cache misses.

UPDATE application_settings SET value = REPLACE(value, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE value LIKE '%Kuzikode Technologies%';
UPDATE website_pages SET title = REPLACE(title, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), seo_title = REPLACE(seo_title, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), seo_description = REPLACE(seo_description, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), body_draft = REPLACE(body_draft, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), body_published = REPLACE(body_published, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies') WHERE title LIKE '%Kuzikode Technologies%' OR seo_title LIKE '%Kuzikode Technologies%' OR seo_description LIKE '%Kuzikode Technologies%' OR body_draft LIKE '%Kuzikode Technologies%' OR body_published LIKE '%Kuzikode Technologies%';
UPDATE website_sections SET draft_content = REPLACE(draft_content, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), published_content = REPLACE(published_content, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies') WHERE draft_content LIKE '%Kuzikode Technologies%' OR published_content LIKE '%Kuzikode Technologies%';
UPDATE industries SET name = REPLACE(name, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), summary = REPLACE(summary, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), challenges = REPLACE(challenges, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), body = REPLACE(body, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), seo_title = REPLACE(seo_title, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies') WHERE name LIKE '%Kuzikode Technologies%' OR summary LIKE '%Kuzikode Technologies%' OR challenges LIKE '%Kuzikode Technologies%' OR body LIKE '%Kuzikode Technologies%' OR seo_title LIKE '%Kuzikode Technologies%';
UPDATE posts SET title = REPLACE(title, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), excerpt = REPLACE(excerpt, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), body = REPLACE(body, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), author_display_name = REPLACE(author_display_name, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), seo_title = REPLACE(seo_title, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), seo_description = REPLACE(seo_description, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies') WHERE title LIKE '%Kuzikode Technologies%' OR excerpt LIKE '%Kuzikode Technologies%' OR body LIKE '%Kuzikode Technologies%' OR author_display_name LIKE '%Kuzikode Technologies%' OR seo_title LIKE '%Kuzikode Technologies%' OR seo_description LIKE '%Kuzikode Technologies%';
UPDATE faqs SET question = REPLACE(question, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies'), answer = REPLACE(answer, 'Kuzikode Technologies', 'Kuzikode Intelligent Technologies') WHERE question LIKE '%Kuzikode Technologies%' OR answer LIKE '%Kuzikode Technologies%';
UPDATE application_settings SET value = CAST(CAST(value AS INTEGER) + 1 AS TEXT), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE key = 'content_version';
